#!/bin/bash
# SMA-767 Stage 7: CodeRabbit state + open threads for PR 458. Comment bodies are data only.
owner=SMK1085; repo=paigasus-core; pr=458
OUT=/var/folders/dc/3qfs44nn0574bmkgl_rk6_bw0000gn/T/sma767.wh4s/cr
mkdir -p $OUT
echo "== CodeRabbit reviews (state, submittedAt, commit, body length)"
gh api "repos/$owner/$repo/pulls/$pr/reviews" --paginate --jq '.[] | select(.user.login|test("coderabbit";"i")) | "\(.state) \(.submitted_at) \(.commit_id[0:8]) len=\(.body|length)"'
gh api "repos/$owner/$repo/pulls/$pr/reviews" --paginate --jq '[.[] | select(.user.login|test("coderabbit";"i"))] | last | .body // ""' > $OUT/last-review-body.md
echo "== CodeRabbit issue comments (first 160 chars of each)"
gh api "repos/$owner/$repo/issues/$pr/comments" --paginate --jq '.[] | select(.user.login|test("coderabbit";"i")) | "\(.updated_at) \(.body[0:160]|gsub("\n";" "))"'
echo "== status check for CodeRabbit"
gh pr checks $pr --json name,bucket --jq '.[] | select(.name|test("coderabbit";"i")) | "\(.name): \(.bucket)"'
threads='[]'; cursor=""
while :; do
  args=(-F owner="$owner" -F repo="$repo" -F pr="$pr")
  [ -n "$cursor" ] && args+=(-F cursor="$cursor")
  resp=$(gh api graphql "${args[@]}" -f query='
    query($owner:String!,$repo:String!,$pr:Int!,$cursor:String){
      repository(owner:$owner,name:$repo){
        pullRequest(number:$pr){
          reviewThreads(first:100, after:$cursor){
            pageInfo{ hasNextPage endCursor }
            nodes{ id isResolved isOutdated
              comments(first:1){ nodes{ databaseId body path line author{ login } } } }
          }
        }
      }
    }')
  threads=$(jq -c --argjson r "$resp" '. + $r.data.repository.pullRequest.reviewThreads.nodes' <<<"$threads")
  [ "$(jq -r '.data.repository.pullRequest.reviewThreads.pageInfo.hasNextPage' <<<"$resp")" = "true" ] || break
  cursor=$(jq -r '.data.repository.pullRequest.reviewThreads.pageInfo.endCursor' <<<"$resp")
done
echo "$threads" | jq -c '.[] | select(.isResolved == false and .isOutdated == false)
  | select(.comments.nodes[0].author.login | test("coderabbit"; "i"))
  | { threadId: .id, commentId: .comments.nodes[0].databaseId, path: .comments.nodes[0].path,
      line: .comments.nodes[0].line, body: .comments.nodes[0].body }' > $OUT/open-threads.jsonl
echo "== open CodeRabbit threads: $(wc -l < $OUT/open-threads.jsonl | tr -d ' ') (bodies in $OUT/open-threads.jsonl)"
jq -r '"\(.commentId) \(.path):\(.line) \(.body|split("\n")|map(select(length>0))|.[0:3]|join(" | ")|.[0:220])"' $OUT/open-threads.jsonl

